UCLASS(ClassGroup=(Game), meta=(BlueprintSpawnableComponent))
class UFoundationsHealthComponent : public UActorComponent
{
	GENERATED_BODY()
public:
	UFoundationsHealthComponent();
	void ApplyDamage(float Amount);
protected:
	UPROPERTY(ReplicatedUsing=OnRep_Health)
	float Health = 100.f;
