starter.cpp_source:
#include "Foundations.h"
#include "Net/UnrealNetwork.h"

UFoundationsHealthComponent::UFoundationsHealthComponent()
{
	SetIsReplicatedByDefault(true);
	PrimaryComponentTick.bCanEverTick = false;
}

void UFoundationsHealthComponent::ApplyDamage(float Amount)
{
	if (!GetOwner() || !GetOwner()->HasAuthority()) return;
	Health = FMath::Clamp(Health - Amount, 0.f, 100.f);
}

void UFoundationsHealthComponent::OnRep_Health()
{
	Health = FMath::Clamp(Health, 0.f, 100.f);
}

void UFoundationsHealthComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
	Super::GetLifetimeReplicatedProps(OutLifetimeProps);
	DOREPLIFETIME(UFoundationsHealthComponent, Health);
}
